package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	f, err := os.Open("note.txt")
	if err != nil {
		return
	}
	defer f.Close()
	sc := bufio.NewScanner(f)
	for sc.Scan() {
		fmt.Println(sc.Text())
	}
	if err := sc.Err(); err != nil {
		fmt.Println("scan error:", err)
	}
}

