package solution

import (
	"bufio"
	"os"
	"strings"
)

func CountNonBlank(path string) (int, error) {
	f, err := os.Open(path)
	if err != nil {
		return 0, err // e.g. file missing
	}
	defer f.Close()

	sc := bufio.NewScanner(f)
	count := 0
	for sc.Scan() {
		if strings.TrimSpace(sc.Text()) != "" { // skip empty / whitespace-only
			count++
		}
	}
	return count, sc.Err() // nil on clean EOF
}

