package solution

import (
	"os"
	"path/filepath"
	"testing"
)

func TestCountNonBlank(t *testing.T) {
	dir := t.TempDir()
	p := filepath.Join(dir, "f.txt")
	if err := os.WriteFile(p, []byte("a\n\n  \nb\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	got, err := CountNonBlank(p)
	if err != nil {
		t.Fatal(err)
	}
	if got != 2 {
		t.Errorf("CountNonBlank = %d, want 2", got)
	}
	if _, err := CountNonBlank(filepath.Join(dir, "nope.txt")); err == nil {
		t.Error("expected an error for a missing file")
	}
}

